// Pure mapping: plotshape / plotchar / plotarrow → lightweight-charts markers.
// LWC has four marker shapes; Pine has twelve. The nearest-glyph table below is
// the whole compromise — anything not an arrow or a circle becomes a square.
const SHAPE_GLYPHS = {
    arrowup: "arrowUp",
    arrowdown: "arrowDown",
    triangleup: "arrowUp",
    triangledown: "arrowDown",
    circle: "circle",
    xcross: "square",
    cross: "square",
    flag: "square",
    square: "square",
    diamond: "square",
    labelup: "arrowUp",
    labeldown: "arrowDown",
};
const LOCATIONS = {
    abovebar: "aboveBar",
    belowbar: "belowBar",
    top: "aboveBar",
    bottom: "belowBar",
    absolute: "inBar",
};
const SIZES = {
    tiny: 0.6,
    small: 0.8,
    auto: 1,
    normal: 1,
    large: 1.5,
    huge: 2,
};
const FALLBACK_COLOR = "#2196F3";
function colorAt(base, perBar, i) {
    return perBar?.[i] ?? base ?? FALLBACK_COLOR;
}
export function shapeMarkers(shape, times) {
    const glyph = SHAPE_GLYPHS[shape.style] ?? "square";
    const position = LOCATIONS[shape.location] ?? "aboveBar";
    const size = SIZES[shape.size] ?? 1;
    const out = [];
    shape.condition.forEach((on, i) => {
        const time = times[i];
        if (!on || time === undefined)
            return;
        out.push({
            time,
            position,
            shape: glyph,
            color: colorAt(shape.color, shape.colors, i),
            size,
            ...(shape.text !== null ? { text: shape.text } : {}),
        });
    });
    return out;
}
export function charMarkers(char, times) {
    const position = LOCATIONS[char.location] ?? "aboveBar";
    const size = SIZES[char.size] ?? 1;
    const out = [];
    char.condition.forEach((on, i) => {
        const time = times[i];
        if (!on || time === undefined)
            return;
        // The character itself rides in `text` — LWC has no custom glyph shape, so the
        // marker circle is shrunk and the char carries the meaning.
        out.push({
            time,
            position,
            shape: "circle",
            color: colorAt(char.color, char.colors, i),
            size: Math.min(size, 0.6),
            text: char.text !== null ? `${char.char} ${char.text}` : char.char,
        });
    });
    return out;
}
export function arrowMarkers(arrow, times) {
    const out = [];
    arrow.values.forEach((v, i) => {
        const time = times[i];
        if (v === null || v === 0 || !Number.isFinite(v) || time === undefined)
            return;
        out.push({
            time,
            position: v > 0 ? "belowBar" : "aboveBar", // TV draws up-arrows under the bar
            shape: v > 0 ? "arrowUp" : "arrowDown",
            color: (v > 0 ? arrow.colorup : arrow.colordown) ?? (v > 0 ? "#4CAF50" : "#FF5252"),
        });
    });
    return out;
}
